+    }
+
+    /**
+     * Average two {@code long}s without any overflow.
+     */
+    static long avgWithoutOverflow(long a, long b) {
+        var value = (a & b) + ((a ^ b) >> 1);
+        // This method rounds negative values down instead of towards zero, like (a + b) / 2 would.
