+                );
+            }
+        });
+        ints(cases, "mv_median_absolute_deviation", "MvMedianAbsoluteDeviation", (size, values) -> {
+            var mad = calculateMedianAbsoluteDeviation(size, values.mapToObj(BigInteger::valueOf));
